def fridge(temp):
    if temp < 2:
        return "too cold"
    elif temp <= 8:
        return "ok"
    return "too warm"

def grade(score):
    if score < 0 or score > 100:
        return "invalid"
    if score >= 80:
        return "A"
    if score >= 65:
        return "B"
    if score >= 50:
        return "C"
    if score >= 40:
        return "D"
    return "E"
